func ElectLeader(
  peers []Peer, counter *TicketCounter,
) (string, error) {
  minTicket := counter.FetchAndAdd(1)
  winner := selfID
  for _, p := range peers { // waits for all
    t, id, err := p.FetchTicketBlocking()
    if err != nil {
      return "", err
    }
    if t < minTicket {
      minTicket, winner = t, id
    }
  }
  return winner, nil
}
